import{_ as a,o as t,c as s,a2 as r}from"./chunks/framework.hw3Av5Vn.js";const n="/llamatron/assets/swell_editor.CUZzRXI9.svg",S=JSON.parse('{"title":"Swell","description":"","frontmatter":{},"headers":[],"relativePath":"generators/SWELL.md","filePath":"generators/SWELL.md"}'),o={name:"generators/SWELL.md"};function l(i,e,h,c,p,d){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="swell" tabindex="-1">Swell <a class="header-anchor" href="#swell" aria-label="Permalink to &quot;Swell&quot;">​</a></h1><p>Swell scales each note&#39;s velocity, held from 1 to 127, for crescendos and fades. A Swell generator also has an Accent, which makes the beats louder still, up to 50%. Swell is one of the three shapes, each a percentage that ramps from a start to an end, which <a href="./../GENERATORS#shapes">Generators</a> describes: where each is set, which wins, and the settings they share. The Swell percentage runs from 0% to 200%.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p><img src="'+n+'" alt="A Swell generator&#39;s settings, with its Accent"></p><p>The settings are those every shape shares, which <a href="./../GENERATORS#shapes">Generators</a> describes.</p><h2 id="applying-the-generator" tabindex="-1">Applying the Generator <a class="header-anchor" href="#applying-the-generator" aria-label="Permalink to &quot;Applying the Generator&quot;">​</a></h2><p>Set Swell in the <code>+ Swell</code> section of a Scene page or a clip page, or make a Swell generator and add it to a chain, as <code>swell: name</code>, to paint one shape on many clips and change it in one place. <code>examples/learning/16_bolero_swell.yml</code> is one long crescendo.</p>',7)])])}const _=a(o,[["render",l]]);export{S as __pageData,_ as default};
